"""Reviewed Russian contracts and independent examples for imported exercises.

Keys are original platform slugs, not display titles (which were truncated by
the old import). References are development-only; never sent to students.
"""
from __future__ import annotations

from dataclasses import dataclass
import collections
import itertools
import math
import re


@dataclass
class Repair:
    platform: str
    slugs: tuple[str, ...]
    contract: str
    samples: list
    source: str
    compare: str = "json"

    def reference(self):
        namespace = {}
        exec("import math, collections, itertools, re\n" + self.source, namespace)
        return namespace["solve"]


